      "Jadwalkan meeting (online/offline), siapkan 5 pertanyaan wajib (harga, overtime, pembatalan, personel, contoh kerja).",
      "Setelah meeting, update tabel banding dengan skor 1–5.",
      "Tulis rekomendasi singkat: vendor A karena … (boleh dibaca orang tua).",
      "Simpan bukti “RFP Undangan cetak + digital + website” di folder bersama (foto/chat/file/kontrak/kwitansi).",
      "Tulis di Catatan Jadwal ringkasan hasil “RFP Undangan cetak + digital + website” + link bukti.",
      "Jika “RFP Undangan cetak + digital + website” belum beres, status = Terhambat + penyebabnya.",
      "Jika “RFP Undangan cetak + digital + website” beres, status = Selesai dan persen 100.",
      "Kabari pihak yang menunggu hasil “RFP Undangan cetak + digital + website” (lihat Pekerjaan berikutnya di panel kanan)."
