    "selesai_bila": "“RFP Undangan cetak + digital + website” dianggap selesai jika hasil di atas ada, bukti tersimpan, status Jadwal = Selesai (atau Terhambat dengan alasan jelas), dan pihak terkait sudah dikabari.",
    "hindari": "Menandai Selesai tanpa bukti; mengerjakan sendirian tanpa kabari penanggung jawab; melewatkan syarat sebelumnya tanpa izin. Jangan cetak massal sebelum nama/tanggal/jam dicek 2 orang."
